// ═══ KOS AUTO-EXPANSION SYNTHESIS ENGINE ═══
const staleSources = $input.all()[0]?.json || [];
const pendingCount = $input.all()[1]?.headers?.content_range ? parseInt($input.all()[1].headers.content_range.split('/')[1]) : 0;
const staleAgents = $input.all()[2]?.json || [];
const qdrantStatus = $input.all()[3]?.json || {};

const now = new Date().toISOString();

// Build expansion decision engine
const expansion = {
  timestamp: now,
  decisions: [],
  summary: {
    sources_to_crawl: staleSources.length,
    pending_embeddings: pendingCount,
    agents_to_reactivate: staleAgents.length,
    qdrant_collections_ok: qdrantStatus.result?.collections?.length > 0 || false,
    action_required: false
  }
};

// Decision 1: Trigger crawls for stale sources
if (staleSources.length > 0) {
  expansion.summary.action_required = true;
  for (const source of staleSources) {
    expansion.decisions.push({
      type: 'crawl_source',
      source_id: source.id,
      source_name: source.name,
      source_url: source.url,
      regulator: source.regulator,
      priority: source.priority || 'medium',
      reason: 'stale_source',
      last_crawled: source.last_crawled_at
    });
  }
}

// Decision 2: Trigger embedding for pending documents
if (pendingCount > 0) {
  expansion.summary.action_required = true;
  expansion.decisions.push({
    type: 'embed_documents',
    count: pendingCount,
    priority: 'high',
    reason: 'pending_embeddings',
    target_collections: ['kos_regulatory_knowledge', 'kos_business_knowledge']
  });
}

// Decision 3: Reactivate stale agents
if (staleAgents.length > 0) {
  expansion.summary.action_required = true;
  for (const agent of staleAgents) {
    expansion.decisions.push({
      type: 'reactivate_agent',
      agent_id: agent.id,
      agent_name: agent.name,
      agent_type: agent.agent_type,
      last_run: agent.last_run_at
    });
  }
}

// Decision 4: Optimize Qdrant collections if fragmentation > 20%
if (expansion.summary.qdrant_collections_ok) {
  expansion.decisions.push({
    type: 'optimize_qdrant',
    collections: qdrantStatus.result?.collections?.map(c => c.name) || [],
    reason: 'routine_optimization'
  });
}

return expansion;

// ═══ EXECUTE CRAWL DECISIONS ═══
const expansion = $input.all()[0]?.json;
const crawlDecisions = (expansion.decisions || []).filter(d => d.type === 'crawl_source');

if (crawlDecisions.length === 0) {
  return { executed: false, reason: 'no_crawl_decisions' };
}

// Build crawl payloads
const crawlPayloads = crawlDecisions.map(d => ({
  source_id: d.source_id,
  source_name: d.source_name,
  source_url: d.source_url,
  regulator: d.regulator,
  priority: d.priority,
  timestamp: new Date().toISOString()
}));

return {
  executed: true,
  count: crawlPayloads.length,
  payloads: crawlPayloads
};

// ═══ EXECUTE EMBEDDING DECISIONS ═══
const expansion = $input.all()[0]?.json;
const embedDecisions = (expansion.decisions || []).filter(d => d.type === 'embed_documents');

if (embedDecisions.length === 0) {
  return { executed: false };
}

return {
  executed: true,
  count: embedDecisions[0]?.count || 0,
  collections: embedDecisions[0]?.target_collections || []
};

// ═══ EXECUTE AGENT REACTIVATION ═══
const expansion = $input.all()[0]?.json;
const agentDecisions = (expansion.decisions || []).filter(d => d.type === 'reactivate_agent');

if (agentDecisions.length === 0) {
  return { executed: false };
}

const agentPayloads = agentDecisions.map(d => ({
  agent_id: d.agent_id,
  agent_name: d.agent_name,
  trigger: 'auto_expansion',
  timestamp: new Date().toISOString()
}));

return {
  executed: true,
  count: agentPayloads.length,
  agents: agentPayloads
};

// ═══ COMPILE EXPANSION EXECUTION REPORT ═══
const crawlResult = $input.all()[0]?.json || {};
const embedResult = $input.all()[1]?.json || {};
const agentResult = $input.all()[2]?.json || {};
const qdrantCheck = $input.all()[3]?.json || {};

const report = {
  timestamp: new Date().toISOString(),
  cycle: 'auto_expansion',
  executions: {
    crawls_triggered: crawlResult.count || 0,
    embeddings_triggered: embedResult.count || 0,
    agents_reactivated: agentResult.count || 0,
    qdrant_healthy: qdrantCheck.result ? true : false
  },
  status: 'completed'
};

return report;

// ═══ AUTO-EXPANSION NO-OP — Nothing to expand ═══
return {
  timestamp: new Date().toISOString(),
  cycle: 'auto_expansion',
  status: 'no_action_required',
  message: 'All systems optimal — no expansion needed this cycle.'
};
